// scripts/plugins/Jammanna_MakeIt3D/c3runtime/threejscore/Pass.js
( function () {

	class Pass {

		constructor() {

			// if set to true, the pass is processed by the composer
			this.enabled = true;

			// if set to true, the pass indicates to swap read and write buffer after rendering
			this.needsSwap = true;

			// if set to true, the pass clears its buffer before rendering
			this.clear = false;

			// if set to true, the result of the pass is rendered to screen. This is set automatically by EffectComposer.
			this.renderToScreen = false;

		}
		setSize() {}
		render() {

			console.error( 'THREE.Pass: .render() must be implemented in derived pass.' );

		}
		dispose() {}

	}

	// Helper for passes that need to fill the viewport with a single quad.

	const _camera = new THREE.OrthographicCamera( - 1, 1, 1, - 1, 0, 1 );

	// https://github.com/mrdoob/three.js/pull/21358

	const _geometry = new THREE.BufferGeometry();
	_geometry.setAttribute( 'position', new THREE.Float32BufferAttribute( [ - 1, 3, 0, - 1, - 1, 0, 3, - 1, 0 ], 3 ) );
	_geometry.setAttribute( 'uv', new THREE.Float32BufferAttribute( [ 0, 2, 0, 0, 2, 0 ], 2 ) );
	class FullScreenQuad {

		constructor( material ) {

			this._mesh = new THREE.Mesh( _geometry, material );

		}
		dispose() {

			this._mesh.geometry.dispose();

		}
		render( renderer ) {

			renderer.render( this._mesh, _camera );

		}
		get material() {

			return this._mesh.material;

		}
		set material( value ) {

			this._mesh.material = value;

		}

	}

	THREE.FullScreenQuad = FullScreenQuad;
	THREE.Pass = Pass;

} )();


// scripts/plugins/Jammanna_MakeIt3D/c3runtime/threejscore/RenderTransitionPass.js
(function () {

    class RenderTransitionPass extends THREE.Pass {

        constructor(sceneA, cameraA, sceneB, cameraB) {
            super();

            this.sceneA = sceneA;
            this.cameraA = cameraA;
            this.sceneB = sceneB;
            this.cameraB = cameraB;

            this.material = this._createMaterial();

            this._renderTargetA = new THREE.WebGLRenderTarget();
            this._renderTargetA.texture.type = THREE.HalfFloatType;

            this._renderTargetB = new THREE.WebGLRenderTarget();
            this._renderTargetB.texture.type = THREE.HalfFloatType;

            this._fsQuad = new THREE.FullScreenQuad(this.material);
        }

        setTransition(value) {
            this.material.uniforms.mixRatio.value = value;
        }

        useTexture(value) {
            this.material.uniforms.useTexture.value = value ? 1 : 0;
        }

        setTexture(value) {
            this.material.uniforms.tMixTexture.value = value;
        }

        setTextureThreshold(value) {
            this.material.uniforms.threshold.value = value;
        }

        setSize(width, height) {
            this._renderTargetA.setSize(width, height);
            this._renderTargetB.setSize(width, height);
        }

        render(renderer, writeBuffer) {
            renderer.setRenderTarget(this._renderTargetA);
            renderer.render(this.sceneA, this.cameraA);
            renderer.setRenderTarget(this._renderTargetB);
            renderer.render(this.sceneB, this.cameraB);

            const uniforms = this._fsQuad.material.uniforms;
            uniforms.tDiffuse1.value = this._renderTargetA.texture;
            uniforms.tDiffuse2.value = this._renderTargetB.texture;

            if (this.renderToScreen) {
                renderer.setRenderTarget(null);
                renderer.clear();
            } else {
                renderer.setRenderTarget(writeBuffer);
                if (this.clear) renderer.clear();
            }

            this._fsQuad.render(renderer);
        }

        dispose() {
            this.material.dispose();
            this._renderTargetA.dispose();
            this._renderTargetB.dispose();
            this._fsQuad.dispose();
        }

        _createMaterial() {
            return new THREE.ShaderMaterial({
                uniforms: {
                    tDiffuse1: { value: null },
                    tDiffuse2: { value: null },
                    mixRatio: { value: 0.0 },
                    threshold: { value: 0.1 },
                    useTexture: { value: 1 },
                    tMixTexture: { value: null }
                },
                vertexShader: `
          varying vec2 vUv;
          void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          }
        `,
                fragmentShader: `
          uniform float mixRatio;
          uniform sampler2D tDiffuse1;
          uniform sampler2D tDiffuse2;
          uniform sampler2D tMixTexture;
          uniform int useTexture;
          uniform float threshold;
          varying vec2 vUv;

          void main() {
            vec4 texel1 = texture2D(tDiffuse1, vUv);
            vec4 texel2 = texture2D(tDiffuse2, vUv);

            if (useTexture == 1) {
              vec4 transitionTexel = texture2D(tMixTexture, vUv);
              float r = mixRatio * (1.0 + threshold * 2.0) - threshold;
              float mixf = clamp((transitionTexel.r - r) * (1.0 / threshold), 0.0, 1.0);
              gl_FragColor = mix(texel1, texel2, mixf);
            } else {
              gl_FragColor = mix(texel2, texel1, mixRatio);
            }
          }
        `
            });
        }
    }

    // Attach to THREE namespace
    THREE.RenderTransitionPass = RenderTransitionPass;

})();


// scripts/plugins/Jammanna_MakeIt3D/c3runtime/threejscore/RGBShiftShader.js
( function () {

	/**
 * RGB Shift Shader
 * Shifts red and blue channels from center in opposite directions
 * Ported from http://kriss.cx/tom/2009/05/rgb-shift/
 * by Tom Butterworth / http://kriss.cx/tom/
 *
 * amount: shift distance (1 is width of input)
 * angle: shift angle in radians
 */

	const RGBShiftShader = {
		uniforms: {
			'tDiffuse': {
				value: null
			},
			'amount': {
				value: 0.005
			},
			'angle': {
				value: 0.0
			}
		},
		vertexShader: /* glsl */`

		varying vec2 vUv;

		void main() {

			vUv = uv;
			gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );

		}`,
		fragmentShader: /* glsl */`

		uniform sampler2D tDiffuse;
		uniform float amount;
		uniform float angle;

		varying vec2 vUv;

		void main() {

			vec2 offset = amount * vec2( cos(angle), sin(angle));
			vec4 cr = texture2D(tDiffuse, vUv + offset);
			vec4 cga = texture2D(tDiffuse, vUv);
			vec4 cb = texture2D(tDiffuse, vUv - offset);
			gl_FragColor = vec4(cr.r, cga.g, cb.b, cga.a);

		}`
	};

	THREE.RGBShiftShader = RGBShiftShader;

} )();


// scripts/plugins/Jammanna_MakeIt3D/c3runtime/threejscore/DepthLimitedBlurShader.js
( function () {

	/**
 * TODO
 */

	const DepthLimitedBlurShader = {
		defines: {
			'KERNEL_RADIUS': 4,
			'DEPTH_PACKING': 1,
			'PERSPECTIVE_CAMERA': 1
		},
		uniforms: {
			'tDiffuse': {
				value: null
			},
			'size': {
				value: new THREE.Vector2( 512, 512 )
			},
			'sampleUvOffsets': {
				value: [ new THREE.Vector2( 0, 0 ) ]
			},
			'sampleWeights': {
				value: [ 1.0 ]
			},
			'tDepth': {
				value: null
			},
			'cameraNear': {
				value: 10
			},
			'cameraFar': {
				value: 1000
			},
			'depthCutoff': {
				value: 10
			}
		},
		vertexShader: /* glsl */`

		#include <common>

		uniform vec2 size;

		varying vec2 vUv;
		varying vec2 vInvSize;

		void main() {
			vUv = uv;
			vInvSize = 1.0 / size;

			gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
		}`,
		fragmentShader: /* glsl */`

		#include <common>
		#include <packing>

		uniform sampler2D tDiffuse;
		uniform sampler2D tDepth;

		uniform float cameraNear;
		uniform float cameraFar;
		uniform float depthCutoff;

		uniform vec2 sampleUvOffsets[ KERNEL_RADIUS + 1 ];
		uniform float sampleWeights[ KERNEL_RADIUS + 1 ];

		varying vec2 vUv;
		varying vec2 vInvSize;

		float getDepth( const in vec2 screenPosition ) {
			#if DEPTH_PACKING == 1
			return unpackRGBAToDepth( texture2D( tDepth, screenPosition ) );
			#else
			return texture2D( tDepth, screenPosition ).x;
			#endif
		}

		float getViewZ( const in float depth ) {
			#if PERSPECTIVE_CAMERA == 1
			return perspectiveDepthToViewZ( depth, cameraNear, cameraFar );
			#else
			return orthographicDepthToViewZ( depth, cameraNear, cameraFar );
			#endif
		}

		void main() {
			float depth = getDepth( vUv );
			if( depth >= ( 1.0 - EPSILON ) ) {
				discard;
			}

			float centerViewZ = -getViewZ( depth );
			bool rBreak = false, lBreak = false;

			float weightSum = sampleWeights[0];
			vec4 diffuseSum = texture2D( tDiffuse, vUv ) * weightSum;

			for( int i = 1; i <= KERNEL_RADIUS; i ++ ) {

				float sampleWeight = sampleWeights[i];
				vec2 sampleUvOffset = sampleUvOffsets[i] * vInvSize;

				vec2 sampleUv = vUv + sampleUvOffset;
				float viewZ = -getViewZ( getDepth( sampleUv ) );

				if( abs( viewZ - centerViewZ ) > depthCutoff ) rBreak = true;

				if( ! rBreak ) {
					diffuseSum += texture2D( tDiffuse, sampleUv ) * sampleWeight;
					weightSum += sampleWeight;
				}

				sampleUv = vUv - sampleUvOffset;
				viewZ = -getViewZ( getDepth( sampleUv ) );

				if( abs( viewZ - centerViewZ ) > depthCutoff ) lBreak = true;

				if( ! lBreak ) {
					diffuseSum += texture2D( tDiffuse, sampleUv ) * sampleWeight;
					weightSum += sampleWeight;
				}

			}

			gl_FragColor = diffuseSum / weightSum;
		}`
	};
	const BlurShaderUtils = {
		createSampleWeights: function ( kernelRadius, stdDev ) {

			const weights = [];
			for ( let i = 0; i <= kernelRadius; i ++ ) {

				weights.push( gaussian( i, stdDev ) );

			}

			return weights;

		},
		createSampleOffsets: function ( kernelRadius, uvIncrement ) {

			const offsets = [];
			for ( let i = 0; i <= kernelRadius; i ++ ) {

				offsets.push( uvIncrement.clone().multiplyScalar( i ) );

			}

			return offsets;

		},
		configure: function ( material, kernelRadius, stdDev, uvIncrement ) {

			material.defines[ 'KERNEL_RADIUS' ] = kernelRadius;
			material.uniforms[ 'sampleUvOffsets' ].value = BlurShaderUtils.createSampleOffsets( kernelRadius, uvIncrement );
			material.uniforms[ 'sampleWeights' ].value = BlurShaderUtils.createSampleWeights( kernelRadius, stdDev );
			material.needsUpdate = true;

		}
	};
	function gaussian( x, stdDev ) {

		return Math.exp( - ( x * x ) / ( 2.0 * ( stdDev * stdDev ) ) ) / ( Math.sqrt( 2.0 * Math.PI ) * stdDev );

	}

	THREE.BlurShaderUtils = BlurShaderUtils;
	THREE.DepthLimitedBlurShader = DepthLimitedBlurShader;

} )();


// scripts/plugins/Jammanna_MakeIt3D/c3runtime/threejscore/OutputShader.js
(function () {

    THREE.OutputShader = {

        name: 'OutputShader',

        uniforms: {
            'tDiffuse': { value: null },
            'toneMappingExposure': { value: 1 }
        },

        vertexShader: `
      precision highp float;

      uniform mat4 modelViewMatrix;
      uniform mat4 projectionMatrix;

      attribute vec3 position;
      attribute vec2 uv;

      varying vec2 vUv;

      void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
      }
    `,

        fragmentShader: `
      precision highp float;

      uniform sampler2D tDiffuse;
      uniform float toneMappingExposure;

      varying vec2 vUv;

      vec3 LinearToneMapping(vec3 color) {
        return toneMappingExposure * color;
      }

      vec3 ReinhardToneMapping(vec3 color) {
        return toneMappingExposure * color / (toneMappingExposure * color + vec3(1.0));
      }

      vec3 CineonToneMapping(vec3 color) {
        color *= toneMappingExposure;
        color = max(vec3(0.0), color - 0.004);
        return pow((color * 1.6) + 0.0031308, vec3(0.41666)) * 1.0;
      }

      vec3 ACESFilmicToneMapping(vec3 color) {
        color *= toneMappingExposure * 0.6;
        return clamp((color * (2.51 * color + 0.03)) / (color * (2.43 * color + 0.59) + 0.14), 0.0, 1.0);
      }

      vec3 AgXToneMapping(vec3 color) {
        return pow(color * toneMappingExposure, vec3(1.0 / 2.2));
      }

      vec3 NeutralToneMapping(vec3 color) {
        color *= toneMappingExposure;
        return clamp((color - 0.004) * (6.2 * color + 0.5) /
                     (color * (6.2 * color + 1.7) + 0.06), 0.0, 1.0);
      }

      vec3 CustomToneMapping(vec3 color) {
        return color * toneMappingExposure;
      }

      vec4 sRGBTransferOETF(vec4 linear) {
  vec3 result;
  float threshold = 0.0031308;
  float a = 12.92;
  float b = 1.055;
  float gamma = 1.0 / 2.4;

  if (linear.r <= threshold) {
    result.r = linear.r * a;
  } else {
    result.r = b * pow(linear.r, gamma) - 0.055;
  }

  if (linear.g <= threshold) {
    result.g = linear.g * a;
  } else {
    result.g = b * pow(linear.g, gamma) - 0.055;
  }

  if (linear.b <= threshold) {
    result.b = linear.b * a;
  } else {
    result.b = b * pow(linear.b, gamma) - 0.055;
  }

  return vec4(result, linear.a);
}

      void main() {
        vec4 texel = texture2D(tDiffuse, vUv);

        // Tone Mapping
        #ifdef LINEAR_TONE_MAPPING
          texel.rgb = LinearToneMapping(texel.rgb);
        #elif defined(REINHARD_TONE_MAPPING)
          texel.rgb = ReinhardToneMapping(texel.rgb);
        #elif defined(CINEON_TONE_MAPPING)
          texel.rgb = CineonToneMapping(texel.rgb);
        #elif defined(ACES_FILMIC_TONE_MAPPING)
          texel.rgb = ACESFilmicToneMapping(texel.rgb);
        #elif defined(AGX_TONE_MAPPING)
          texel.rgb = AgXToneMapping(texel.rgb);
        #elif defined(NEUTRAL_TONE_MAPPING)
          texel.rgb = NeutralToneMapping(texel.rgb);
        #elif defined(CUSTOM_TONE_MAPPING)
          texel.rgb = CustomToneMapping(texel.rgb);
        #endif

        // Color space transform
        #ifdef SRGB_TRANSFER
          texel = sRGBTransferOETF(texel);
        #endif

        gl_FragColor = texel;
      }
    `
    };

})();


// scripts/plugins/Jammanna_MakeIt3D/c3runtime/threejscore/OutputPass.js
(function () {

    class OutputPass extends THREE.Pass {

        constructor() {
            super();

            this.uniforms = THREE.UniformsUtils.clone(THREE.OutputShader.uniforms);

            this.material = new THREE.RawShaderMaterial({
                name: THREE.OutputShader.name,
                uniforms: this.uniforms,
                vertexShader: THREE.OutputShader.vertexShader,
                fragmentShader: THREE.OutputShader.fragmentShader
            });

            this._fsQuad = new THREE.FullScreenQuad(this.material);
            this._outputColorSpace = null;
            this._toneMapping = null;
        }

        render(renderer, writeBuffer, readBuffer) {
            this.uniforms['tDiffuse'].value = readBuffer.texture;
            this.uniforms['toneMappingExposure'].value = renderer.toneMappingExposure;

            if (this._outputColorSpace !== renderer.outputColorSpace || this._toneMapping !== renderer.toneMapping) {
                this._outputColorSpace = renderer.outputColorSpace;
                this._toneMapping = renderer.toneMapping;

                this.material.defines = {};

                // 🔧 Use the correct color space check for latest Three.js
                if (renderer.outputColorSpace === THREE.SRGBColorSpace) {
                    this.material.defines.SRGB_TRANSFER = '';
                }

                switch (renderer.toneMapping) {
                    case THREE.LinearToneMapping: this.material.defines.LINEAR_TONE_MAPPING = ''; break;
                    case THREE.ReinhardToneMapping: this.material.defines.REINHARD_TONE_MAPPING = ''; break;
                    case THREE.CineonToneMapping: this.material.defines.CINEON_TONE_MAPPING = ''; break;
                    case THREE.ACESFilmicToneMapping: this.material.defines.ACES_FILMIC_TONE_MAPPING = ''; break;
                    case THREE.AgXToneMapping: this.material.defines.AGX_TONE_MAPPING = ''; break;
                    case THREE.NeutralToneMapping: this.material.defines.NEUTRAL_TONE_MAPPING = ''; break;
                    case THREE.CustomToneMapping: this.material.defines.CUSTOM_TONE_MAPPING = ''; break;
                }

                this.material.needsUpdate = true;
            }

            const target = this.renderToScreen ? null : writeBuffer;
            renderer.setRenderTarget(target);

            if (!this.renderToScreen && this.clear) {
                renderer.clear(renderer.autoClearColor, renderer.autoClearDepth, renderer.autoClearStencil);
            }

            this._fsQuad.render(renderer);
        }

        dispose() {
            this.material.dispose();
            this._fsQuad.dispose();
        }
    }

    // 🔗 Register the pass on the global THREE object
    THREE.OutputPass = OutputPass;

})();


